import { createIdGenerator } from '../helpers/ids.js';

/**
 * Creates the store of the lending desk, held in memory, from lists of items, members, loans,
 * holds and fees. Every read returns a copy, so that a caller changes a record only by saving it.
 */
export function createStore({ items = [], members = [], loans = [], holds = [], fees = [] } = {}) {
  const tables = {
    items: toTable(items),
    members: toTable(members),
    loans: toTable(loans),
    holds: toTable(holds),
    fees: toTable(fees),
  };
  const nextId = {
    loans: createIdGenerator('loan'),
    holds: createIdGenerator('hold'),
    fees: createIdGenerator('fee'),
  };

  function list(table, keep = () => true) {
    return [...tables[table].values()].filter(keep).map((record) => ({ ...record }));
  }
  function get(table, id) {
    const record = tables[table].get(id);
    return record === undefined ? undefined : { ...record };
  }
  function save(table, record) {
    const saved = { ...record, id: record.id ?? nextId[table]() };
    tables[table].set(saved.id, saved);
    return { ...saved };
  }

  return {
    getItem: (id) => get('items', id),
    listItems: () => list('items'),
    findItemByBarcode: (barcode) => list('items', (item) => item.barcode === barcode)[0],
    getMember: (id) => get('members', id),
    listMembers: () => list('members'),
    getLoan: (id) => get('loans', id),
    listAllLoans: () => list('loans'),
    listOpenLoans: (memberId) =>
      list('loans', (loan) => loan.memberId === memberId && loan.returnedOn === null),
    findOpenLoan: (itemId) => list('loans', (loan) => loan.itemId === itemId && loan.returnedOn === null)[0],
    saveLoan: (loan) => save('loans', loan),
    listHolds: (itemId) => list('holds', (hold) => hold.itemId === itemId),
    listAllHolds: () => list('holds'),
    saveHold: (hold) => save('holds', hold),
    getFee: (id) => get('fees', id),
    listFees: (memberId) => list('fees', (fee) => fee.memberId === memberId),
    saveFee: (fee) => save('fees', fee),
  };
}

function toTable(records) {
  return new Map(records.map((record) => [record.id, { ...record }]));
}
import { searchCatalog } from '../../catalog/search.js';
import { ok } from '../respond.js';

/** The route of catalog search: GET /catalog?q=words. */
export function catalogRoutes(store) {
  return [
    {
      method: 'GET',
      path: '/catalog',
      handle: ({ query }) => ok({ items: searchCatalog(store.listItems(), query?.q ?? '') }),
    },
  ];
}
import { holdQueue, placeHold } from '../../holds/queue.js';
import { fail, ok } from '../respond.js';

/** The routes of holds: placing one, and the queue of an item. */
export function holdRoutes(store) {
  return [
    {
      method: 'POST',
      path: '/holds',
      handle: ({ body, today }) => {
        const result = placeHold(store, { ...body, today });
        return result.ok
          ? ok({ hold: result.hold }, 201)
          : fail(409, result.reason, 'The hold cannot be placed');
      },
    },
    {
      method: 'GET',
      path: '/items/:id/holds',
      handle: ({ params }) => ok({ holds: holdQueue(store, params.id) }),
    },
  ];
}
import assert from 'node:assert/strict';
import test from 'node:test';
import { createApp } from '../lib/server/app.js';
import { ADA, BOOK, DVD, sampleLoan, sampleStore, TODAY } from './sample-library.js';

function request(method, path, { body = null, query = {} } = {}) {
  return { method, path, query, body, today: TODAY };
}

test('POST /checkouts lends an item', () => {
  const app = createApp(sampleStore());
  const response = app.handle(
    request('POST', '/checkouts', { body: { barcode: BOOK.barcode, memberId: ADA.id } }),
  );
  assert.equal(response.status, 201);
  assert.equal(response.body.loan.dueOn, '2026-12-17');
});

test('POST /checkouts refuses a barcode with a wrong check digit', () => {
  const app = createApp(sampleStore());
  const response = app.handle(
    request('POST', '/checkouts', { body: { barcode: '31234000000017', memberId: ADA.id } }),
  );
  assert.equal(response.status, 400);
  assert.equal(response.body.error.code, 'invalid-barcode');
});

test('POST /loans/:id/renew answers a refusal with its reason as the error code', () => {
  const loan = sampleLoan({
    id: 'loan_1',
    item: DVD,
    member: ADA,
    checkedOutOn: '2026-11-01',
    dueOn: '2026-11-08',
  });
  const app = createApp(sampleStore({ loans: [loan] }));
  const response = app.handle(request('POST', '/loans/loan_1/renew'));
  assert.equal(response.status, 409);
  assert.equal(response.body.error.code, 'overdue');
});

test('GET /members/:id/summary gives the loans and the balance of a member', () => {
  const loan = sampleLoan({
    id: 'loan_1',
    item: BOOK,
    member: ADA,
    checkedOutOn: '2026-11-20',
    dueOn: '2026-12-11',
  });
  const fees = [
    { id: 'fee_1', memberId: ADA.id, loanId: 'loan_0', amountCents: 250, paid: false, waivedReason: null },
  ];
  const app = createApp(sampleStore({ loans: [loan], fees }));
  const response = app.handle(request('GET', `/members/${ADA.id}/summary`));
  assert.equal(response.status, 200);
  assert.equal(response.body.loanCount, 1);
  assert.equal(response.body.balance, '$2.50');
});

